package com.tsk.carmedia
import android.app.*;import android.content.*;import android.graphics.*;import android.hardware.display.DisplayManager;import android.media.*;import android.media.projection.*;import android.os.*;import androidx.core.app.NotificationCompat;import okhttp3.*;import okhttp3.MediaType.Companion.toMediaType;import okhttp3.RequestBody.Companion.toRequestBody;import java.io.ByteArrayOutputStream;import java.util.concurrent.Executors;import java.util.concurrent.atomic.*
class MirrorService:Service(){var mp:MediaProjection?=null;var rd:ImageReader?=null;var vd:android.hardware.display.VirtualDisplay?=null;val ex=Executors.newSingleThreadExecutor();val busy=AtomicBoolean(false);val latest=AtomicReference<ByteArray?>(null);val http=OkHttpClient();var ip="";var sent=0L;var drop=0L
override fun onBind(i:Intent?)=null
override fun onStartCommand(i:Intent?,f:Int,id:Int):Int{val nm=getSystemService(NOTIFICATION_SERVICE) as NotificationManager;nm.createNotificationChannel(NotificationChannel("cm","Car Media",NotificationManager.IMPORTANCE_LOW));startForeground(1,note("Starting"));ip=i!!.getStringExtra("ip")!!;val code=i.getIntExtra("code",0);@Suppress("DEPRECATION") val data=i.getParcelableExtra<Intent>("data")!!;mp=(getSystemService(MEDIA_PROJECTION_SERVICE) as MediaProjectionManager).getMediaProjection(code,data);mp!!.registerCallback(object:MediaProjection.Callback(){override fun onStop(){stopSelf()}},Handler(Looper.getMainLooper()));rd=ImageReader.newInstance(1280,480,PixelFormat.RGBA_8888,2);vd=mp!!.createVirtualDisplay("CarMedia",1280,480,240,DisplayManager.VIRTUAL_DISPLAY_FLAG_AUTO_MIRROR,rd!!.surface,null,null);rd!!.setOnImageAvailableListener({r->val im=r.acquireLatestImage()?:return@setOnImageAvailableListener;try{val p=im.planes[0];val pad=p.rowStride-p.pixelStride*im.width;val w=Bitmap.createBitmap(im.width+pad/p.pixelStride,im.height,Bitmap.Config.ARGB_8888);w.copyPixelsFromBuffer(p.buffer);val b=Bitmap.createBitmap(w,0,0,im.width,im.height);w.recycle();val o=ByteArrayOutputStream();b.compress(Bitmap.CompressFormat.JPEG,40,o);b.recycle();if(latest.getAndSet(o.toByteArray())!=null)drop++;pump()}finally{im.close()}},Handler(Looper.getMainLooper()));return START_NOT_STICKY}
fun pump(){if(!busy.compareAndSet(false,true))return;ex.execute{try{while(true){val j=latest.getAndSet(null)?:break;try{http.newCall(Request.Builder().url("http://$ip:8765/frame").post(j.toRequestBody("image/jpeg".toMediaType())).build()).execute().use{if(it.isSuccessful)sent++}}catch(_:Exception){}}}finally{busy.set(false);if(latest.get()!=null)pump();(getSystemService(NOTIFICATION_SERVICE) as NotificationManager).notify(1,note("Sent $sent • Dropped $drop"))}}}
fun note(s:String)=NotificationCompat.Builder(this,"cm").setContentTitle("Car Media v1.3").setContentText(s).setSmallIcon(android.R.drawable.ic_media_play).setOnlyAlertOnce(true).build()
override fun onDestroy(){rd?.close();vd?.release();mp?.stop();ex.shutdownNow();super.onDestroy()}}